// The server-events node's event_type filter is not honoured by every version
// of node-red-contrib-home-assistant-websocket -- on some it subscribes to the
// whole bus and delivers state_changed for every entity in Home Assistant.
// Filtering here instead makes the flow correct regardless of that. Dropped
// silently: warning on each would flood the debug pane just as badly.
const raw = msg.payload || {};
if (raw.event_type && raw.event_type !== 'ha_stock_app_price_alert') return null;

// Payload is either the bare event data or the full envelope, depending on
// version. Accept both.
const d = raw.event || raw.data || raw;
const TEST = d.test === true;
// Refuse to notify on a payload that does not carry this event's fields.
// Without this, an empty or unexpected payload still produced a notification --
// "undefined NaN%" and friends -- which is how a malformed burst became a flood.
if (d.symbol === undefined || d.change_pct === undefined || d.price === undefined) {
    node.warn('price_alert: unexpected payload, not notifying -> ' + JSON.stringify(msg.payload).slice(0, 300));
    node.status({fill: 'red', shape: 'ring', text: 'bad payload'});
    return null;
}

// v2 parity: icon/sign/channel/colour, and the "Level crossed" figure, which v2
// derived as sign * floor(|pct| / 1.0) * 1.0 with a 1% threshold.
const sym   = d.symbol;
const price = Number(d.price);
const pct   = Number(d.change_pct);
const icon  = pct >= 0 ? '\u{1F7E2}' : '\u{1F534}';
const sign  = pct >= 0 ? '+' : '';
const level = (pct >= 0 ? 1 : -1) * Math.floor(Math.abs(pct) / 1.0) * 1.0;
const label = sym === 'VOO' ? 'VOO (S&P 500)' : sym;

msg.payload = {
    title:   `${icon} ${label} ${sign}${pct.toFixed(2)}% today`,
    message: `${sym} at $${price.toFixed(2)} \u2014 ${sign}${pct.toFixed(2)}% vs prev close. Level crossed: ${sign}${level}%`,
    color:   pct >= 0 ? 'green' : 'red',
    channel: pct <= -2 ? 'stock_alert' : 'Stocks',
    test:    TEST,
    // v2 alerted once per whole-percent level and no more than hourly.
    dedupKey: `price:${sym}:${level}`,
    cooldownMs: 60 * 60 * 1000
};
return msg;

