// of node-red-contrib-home-assistant-websocket -- on some it subscribes to the
// whole bus and delivers state_changed for every entity in Home Assistant.
// Filtering here instead makes the flow correct regardless of that. Dropped
// silently: warning on each would flood the debug pane just as badly.
const raw = msg.payload || {};
if (raw.event_type && raw.event_type !== 'ha_stock_app_eod_summary') return null;

// Payload is either the bare event data or the full envelope, depending on
// version. Accept both.
const d = raw.event || raw.data || raw;
const TEST = d.test === true;
// Refuse to notify on a payload that does not carry this event's fields.
// Without this, an empty or unexpected payload still produced a notification --
// "undefined NaN%" and friends -- which is how a malformed burst became a flood.
if (!d.stocks || Object.keys(d.stocks).length === 0) {
    node.warn('eod_summary: unexpected payload, not notifying -> ' + JSON.stringify(msg.payload).slice(0, 300));
    node.status({fill: 'red', shape: 'ring', text: 'bad payload'});
    return null;
}

// v2 parity: per-line "icon LABEL  $price  +pct%  |  $held  (+$day)", then a
// total line. v2 read holdings from Monarch sensors; the integration now ships
// position_value/day_pl in the event itself.
const stocks = d.stocks || {};
const syms = Object.keys(stocks);

function fmtMoney(val) {
    if (val == null || isNaN(val)) return null;
    return '$' + Math.abs(Math.round(val)).toLocaleString('en-US');
}

let totalHeld = 0, totalDay = 0, haveHeld = false;
const lines = syms.map(sym => {
    const s = stocks[sym];
    const price = Number(s.price), pct = Number(s.change_pct);
    if (isNaN(price) || isNaN(pct)) return `${sym}: no data`;
    const icon = pct >= 0 ? '\u{1F7E2}' : '\u{1F534}';
    const pctSign = pct >= 0 ? '+' : '-';
    let line = `${icon} ${sym}  $${price.toFixed(2)}  ${pctSign}${Math.abs(pct).toFixed(2)}%`;
    if (s.position_value != null && s.day_pl != null) {
        haveHeld = true;
        totalHeld += Number(s.position_value);
        totalDay  += Number(s.day_pl);
        const dcSign = Number(s.day_pl) >= 0 ? '+' : '-';
        line += `  |  ${fmtMoney(s.position_value)}  (${dcSign}${fmtMoney(s.day_pl)})`;
    }
    return line;
});

// v2 badged the summary off the S&P proxy; fall back to the first symbol.
const lead = stocks['VOO'] || stocks[syms[0]];
const leadPct = lead ? Number(lead.change_pct) : null;
let badge = '\u{1F4CA}';
if (leadPct != null && !isNaN(leadPct)) {
    if      (leadPct >= 1)  badge = '\u{1F7E2}';
    else if (leadPct >= 0)  badge = '\u{1F7E1}';
    else if (leadPct >= -1) badge = '\u{1F7E0}';
    else                    badge = '\u{1F534}';
}
// Handed to the 401k formatter, which fires minutes later and wants this figure.
if (leadPct != null && !isNaN(leadPct)) flow.set('lead_pct', leadPct);

const parts = lines.slice();
if (haveHeld) {
    const sign = totalDay >= 0 ? '+' : '-';
    parts.push('', `\u{1F4BC} Total: ${fmtMoney(totalHeld)}  |  Day: ${sign}${fmtMoney(totalDay)}`);
}

msg.payload = {
    title:   `${badge} Market Closed \u2014 Daily Summary`,
    message: parts.join('\n'),
    color:   (leadPct != null && leadPct >= 0) ? 'green' : 'red',
    channel: 'Stocks',
    test:    TEST
};
return msg;

