let message = 'NYSE is now open. Portfolio tracking begins.';
if (d.early_close) message += `\nEarly close today at ${d.close_time} ET.`;

msg.payload = {
    title:   '\u{1F514} Market Open',
    message: message,
    color:   'green',
    channel: 'Stocks',
