const raw = msg.payload || {};
if (raw.event_type && raw.event_type !== 'ha_stock_app_eod2_summary') return null;

// Payload is either the bare event data or the full envelope, depending on
// version. Accept both.
const d = raw.event || raw.data || raw;
const TEST = d.test === true;
// Refuse to notify on a payload that does not carry this event's fields.
// Without this, an empty or unexpected payload still produced a notification --
// "undefined NaN%" and friends -- which is how a malformed burst became a flood.
if (d.new_value === undefined) {
    node.warn('eod2_summary: unexpected payload, not notifying -> ' + JSON.stringify(msg.payload).slice(0, 300));
    node.status({fill: 'red', shape: 'ring', text: 'bad payload'});
    return null;
}

// v2 parity: "old \u2192 new / P/L: \u00b1$x (\u00b1y%) / S&P 500 was z% today".
function fmtMoney(val) {
    if (val == null || isNaN(val)) return 'unavailable';
    return '$' + Math.abs(Math.round(val)).toLocaleString('en-US');
}

const oldVal = Number(d.previous_value);
const newVal = Number(d.new_value);
const pl     = Number(d.day_change);
const plPct  = Number(d.day_change_pct);

const leadPct = flow.get('lead_pct');
const badge = (leadPct != null && !isNaN(leadPct)) ? (leadPct >= 0 ? '\u{1F7E2}' : '\u{1F534}') : '\u{1F4CA}';
const leadStr = (leadPct != null && !isNaN(leadPct))
    ? `${leadPct >= 0 ? '+' : ''}${Number(leadPct).toFixed(2)}%` : 'unavailable';

const havePL = !isNaN(pl);
const plSign = havePL ? (pl >= 0 ? '+' : '-') : '';
const plPctStr = !isNaN(plPct) ? ` (${plSign}${Math.abs(plPct).toFixed(2)}%)` : '';
const plStr = havePL ? `${plSign}${fmtMoney(pl)}${plPctStr}` : 'unavailable';

const lead = !isNaN(oldVal) ? fmtMoney(oldVal) : fmtMoney(newVal);
const changeStr = (!isNaN(oldVal) && !isNaN(newVal)) ? ` \u2192 ${fmtMoney(newVal)}` : '';

let message = `${lead}${changeStr}\nP/L: ${plStr}\nS&P 500 was ${leadStr} today`;
if (d.deferred) message += '\n(held from overnight)';

msg.payload = {
    title:   `${badge} 401k Updated`,
    message: message,
    color:   havePL ? (pl >= 0 ? 'green' : 'red') : 'red',
    channel: 'Stocks',
    test:    TEST
};
return msg;

