}

// v2 parity, including the exact window wording.
const fmt = n => '$' + Math.round(n).toLocaleString('en-US');
const inWindow = d.in_pay_window === true;
const windowText = inWindow ? ' \u2014 lines up with payday' : ' \u2014 outside normal pay window';

msg.payload = {
    title:   inWindow ? '\u{1F4B0} Likely Paycheck' : '\u{1F4B5} Large Cash Increase',
    message: 'Estimated paycheck: ' + fmt(Number(d.amount)) + windowText,
    color:   '#2E7D32',
    channel: 'Network Restored',
    test:    TEST
};
return msg;

// The server-events node's event_type filter is not honoured by every version
// of node-red-contrib-home-assistant-websocket -- on some it subscribes to the
// whole bus and delivers state_changed for every entity in Home Assistant.
// Filtering here instead makes the flow correct regardless of that. Dropped
// silently: warning on each would flood the debug pane just as badly.
const raw = msg.payload || {};
if (raw.event_type && raw.event_type !== 'ha_stock_app_monarch_status') return null;

// Payload is either the bare event data or the full envelope, depending on
// version. Accept both.
const d = raw.event || raw.data || raw;
const TEST = d.test === true;
// Refuse to notify on a payload that does not carry this event's fields.
// Without this, an empty or unexpected payload still produced a notification --
// "undefined NaN%" and friends -- which is how a malformed burst became a flood.
if (d.status !== 'online' && d.status !== 'offline') {
    node.warn('monarch_status: unexpected payload, not notifying -> ' + JSON.stringify(msg.payload).slice(0, 300));
    node.status({fill: 'red', shape: 'ring', text: 'bad payload'});
    return null;
}

// v2 watchdog wording. The integration decides the transition, so the flow no
// longer has to debounce unavailable/unknown states itself.
if (d.status === 'online') {
    msg.payload = {
        title:   '\u2705 Monarch Integration Restored',
        message: 'Monarch sensors are reporting again. Holdings and the P&L sensor are back.',
        color:   '#2E7D32',
        channel: 'Flow Errors'
    };
} else {
    msg.payload = {
        title:   '\u26A0\uFE0F Monarch Integration Down',
        message: 'Monarch sensors are unavailable \u2014 portfolio holdings and the P&L sensor will read $0 until it reconnects. Reload the integration (Settings \u2192 Devices & Services \u2192 Reload) or re-authenticate.',
        color:   '#D32F2F',
        channel: 'Flow Errors'
    };
}
msg.payload.test = TEST;
return msg;

// The server-events node's event_type filter is not honoured by every version
// of node-red-contrib-home-assistant-websocket -- on some it subscribes to the
// whole bus and delivers state_changed for every entity in Home Assistant.
// Filtering here instead makes the flow correct regardless of that. Dropped
// silently: warning on each would flood the debug pane just as badly.
const raw = msg.payload || {};
if (raw.event_type && raw.event_type !== 'ha_stock_app_finnhub_error') return null;

// Payload is either the bare event data or the full envelope, depending on
// version. Accept both.
const d = raw.event || raw.data || raw;
const TEST = d.test === true;
// Refuse to notify on a payload that does not carry this event's fields.
// Without this, an empty or unexpected payload still produced a notification --
// "undefined NaN%" and friends -- which is how a malformed burst became a flood.
if (d.symbol === undefined && d.error === undefined) {
    node.warn('finnhub_error: unexpected payload, not notifying -> ' + JSON.stringify(msg.payload).slice(0, 300));
    node.status({fill: 'red', shape: 'ring', text: 'bad payload'});
    return null;
}

// v2 raised node.error here and the catch-all formatted it; the integration
// publishes the failure directly, so it is formatted in place. The 2h dedup is
// carried over from v2's "Error Dedup + Format".
msg.payload = {
    title:   '\u26A0\uFE0F Finnhub Self-Test Failed',
    message: `Self-test failed for ${d.symbol}: ${d.error}\nQuotes may be broken today.`,
    color:   '#D32F2F',
    channel: 'Flow Errors',
    test:    TEST,
    dedupKey: 'finnhub_error',
    cooldownMs: 2 * 60 * 60 * 1000
};
return msg;

// The server-events node's event_type filter is not honoured by every version
// of node-red-contrib-home-assistant-websocket -- on some it subscribes to the
// whole bus and delivers state_changed for every entity in Home Assistant.
// Filtering here instead makes the flow correct regardless of that. Dropped
// silently: warning on each would flood the debug pane just as badly.
const raw = msg.payload || {};
if (raw.event_type && raw.event_type !== 'ha_stock_app_finnhub_ok') return null;

// Payload is either the bare event data or the full envelope, depending on
// version. Accept both.
const d = raw.event || raw.data || raw;
const TEST = d.test === true;
// Refuse to notify on a payload that does not carry this event's fields.
// Without this, an empty or unexpected payload still produced a notification --
// "undefined NaN%" and friends -- which is how a malformed burst became a flood.
if (d.symbol === undefined || d.price === undefined) {
    node.warn('finnhub_ok: unexpected payload, not notifying -> ' + JSON.stringify(msg.payload).slice(0, 300));
    node.status({fill: 'red', shape: 'ring', text: 'bad payload'});
    return null;
}

// v2 only notified on a *manual* self-test; a passing scheduled test was silent.
// Same here: stay quiet unless this was fired from the integration's test button.
if (!TEST) return null;

msg.payload = {
    title:   '\u2705 Finnhub API OK',
    message: `HTTP 200 - ${d.symbol} $${Number(d.price).toFixed(2)}`,
    color:   '#2E7D32',
    channel: 'Flow Errors',
    test:    TEST
};
return msg;

// Single exit gate: test tagging, repeat suppression, and a hard ceiling.
//
// Two rules earned the hard way:
//   1. Test events are NOT exempt from the ceiling. They were, and because the
//      test button can be pressed repeatedly -- or fired in a loop -- that was
//      the one path with no protection at all. It flooded a phone.
//   2. A formatter that cannot build a real message returns null upstream, so
//      nothing malformed reaches here in the first place.
const p = msg.payload;
if (!p || !p.title) return null;

const now = Date.now();
if (p.test) p.title = '\u{1F9EA} TEST: ' + p.title;

// Burst limit: applies to everything, tests included. Manual testing needs a
// few in quick succession; nothing legitimate needs dozens.
const BURST_MAX = 5, BURST_WINDOW = 60 * 1000;
let burst = (flow.get('burst_times') || []).filter(t => now - t < BURST_WINDOW);
if (burst.length >= BURST_MAX) {
    flow.set('burst_times', burst);
    node.status({fill: 'red', shape: 'ring', text: 'burst limit'});
    node.warn('Burst limit: >' + BURST_MAX + ' notifications in 60s. Dropping: ' + p.title);
    return null;
}

// Hourly ceiling for non-test traffic.
const MAX_PER_HOUR = 12;
let sent = (flow.get('sent_times') || []).filter(t => now - t < 3600000);
if (!p.test && sent.length >= MAX_PER_HOUR) {
    flow.set('sent_times', sent);
    node.status({fill: 'red', shape: 'ring', text: 'hourly ceiling'});
    node.warn('Hourly ceiling reached; suppressing: ' + p.title);
    return null;
}

// Identical-title cooldown for every event type, not just the two that set a key.
const key = p.dedupKey || ('title:' + p.title);
const window = p.cooldownMs || 10 * 60 * 1000;
const seen = flow.get('alert_seen') || {};
for (const k of Object.keys(seen)) if (now - seen[k] > 86400000) delete seen[k];
if (!p.test && seen[key] && now - seen[key] < window) {
    flow.set('alert_seen', seen);
    node.status({fill: 'grey', shape: 'ring', text: 'suppressed'});
    return null;
}
seen[key] = now; flow.set('alert_seen', seen);
burst.push(now); flow.set('burst_times', burst);
if (!p.test) { sent.push(now); flow.set('sent_times', sent); }

delete p.dedupKey; delete p.cooldownMs;
node.status({fill: 'green', shape: 'dot', text: p.title.slice(0, 28)});
return msg;
